<script lang="ts">import { statusColor } from '../format';let { status = 'unknown' }: { status?: string } = $props();</script><span class="dot" style={`background:${statusColor(status)}`} class:pulse={status === 'starting'} aria-label={status}></span><style>.dot{width:8px;height:8px;border-radius:50%;display:inline-block}.pulse{animation:pulse 1.2s infinite}@keyframes pulse{50%{opacity:0.4}}</style>
